export const impostorGlyphs=Object.freeze(Object.fromEntries([["wizard",61440],["tomb",61446],["routes",61452],["paw",61458],["night",61464],["music",61470],["masks",61476],["devil",61482],["cry",61488],["crown",61494],["cross",61500],["candle",61506]].map(([e,r])=>[e,Object.freeze(Array.from({length:6},(e,o)=>String.fromCodePoint(r+o)))])));export function chooseImpostorGlyph(e,r=Math.random,o=null){const t=impostorGlyphs[e];if(!t)return null;const n=t.map((e,r)=>r).filter(e=>e!==o),s=n[Math.floor(r()*n.length)];return Object.freeze({index:s,glyph:t[s]})}
